"query": {
 "match": {
 "general_text": {
 "query": "federal"
 }
 }
},
"knn": {
 "field": "general_text_vector",
 "query_vector": [-9.01364535e-03, -7.26634488e-02, ..., -1.16323479e-01],
 "k": 3,
 "num_candidates": 10
},
"size": 5,
"_source": [
 "general_text"
]
}'


```

